import { concatBytes, readUint16BE, readUint32BE } from './bytes.js';
import { crc32c } from './crc32c.js';
import { reconstructShards } from './reed-solomon.js';

const HEADER_LENGTH = 16;

export function decodeGridEnvelope(wireData) {
  if (wireData.length < HEADER_LENGTH) throw new Error('Grid FEC envelope is truncated');
  const originalLength = readUint32BE(wireData, 0);
  const shardCount = readUint16BE(wireData, 4);
  const dataShardCount = readUint16BE(wireData, 6);
  const shardLength = readUint16BE(wireData, 8);
  const expectedCRC = readUint32BE(wireData, 12);
  if (shardCount === 0 || dataShardCount === 0 || dataShardCount >= shardCount || shardCount > 255) {
    throw new Error('Grid FEC shard metadata is invalid');
  }
  const shardOffset = HEADER_LENGTH + shardCount * 4;
  const byteCount = shardCount * shardLength;
  if (shardOffset + byteCount > wireData.length) throw new Error('Grid FEC shards are truncated');
  const shards = [];
  const present = [];
  for (let index = 0; index < shardCount; index += 1) {
    const start = shardOffset + index * shardLength;
    const shard = Uint8Array.from(wireData.subarray(start, start + shardLength));
    shards.push(shard);
    present.push(crc32c(shard) === readUint32BE(wireData, HEADER_LENGTH + index * 4));
  }
  if (present.some((value) => !value)) {
    reconstructShards(shards, present, dataShardCount, shardLength);
  }
  const reconstructed = concatBytes(...shards);
  if (crc32c(reconstructed) !== expectedCRC) throw new Error('Grid FEC checksum failed');
  if (originalLength > dataShardCount * shardLength) throw new Error('Grid payload length is invalid');
  return reconstructed.slice(0, originalLength);
}

