import { chacha20poly1305 } from '@noble/ciphers/chacha';
import { x25519 } from '@noble/curves/ed25519';
import { hkdf } from '@noble/hashes/hkdf';
import { hmac } from '@noble/hashes/hmac';
import { sha256 } from '@noble/hashes/sha256';
import {
  base64ToBytes,
  bytesToBase64,
  concatBytes,
  equalBytes,
  stableStringify,
  textDecoder,
  textEncoder,
  uint32BE,
  uuidToBytes
} from './bytes.js';
import { CONTROL_PREFIX, PROTOCOL_VERSION } from './constants.js';

export function decodeControlCode(code) {
  if (!code.startsWith(CONTROL_PREFIX)) throw new Error('Invalid OptiLink control code');
  const json = textDecoder.decode(base64ToBytes(code.slice(CONTROL_PREFIX.length)));
  const message = JSON.parse(json);
  if (message.protocolVersion !== PROTOCOL_VERSION) {
    throw new Error(`Unsupported OptiLink protocol version ${message.protocolVersion}`);
  }
  return message;
}

export function encodeControlCode(message) {
  return CONTROL_PREFIX + bytesToBase64(textEncoder.encode(stableStringify(message)));
}

export function offerFromLocation(locationValue = globalThis.location) {
  const hash = locationValue.hash.startsWith('#') ? locationValue.hash.slice(1) : locationValue.hash;
  const offerCode = new URLSearchParams(hash).get('offer');
  if (!offerCode) throw new Error('This receiver link does not contain an OptiLink offer');
  const offer = decodeControlCode(offerCode);
  if (offer.kind !== 'offer' || !offer.publicKey || !offer.sessionID) {
    throw new Error('The browser receiver link contains an invalid offer');
  }
  return { offer, offerCode };
}

export class BrowserSessionCipher {
  constructor(offer, privateKey) {
    this.offer = offer;
    this.sessionIDBytes = uuidToBytes(offer.sessionID);
    this.privateKey = privateKey ?? x25519.utils.randomSecretKey();
    this.publicKey = x25519.getPublicKey(this.privateKey);
    const remotePublicKey = base64ToBytes(offer.publicKey);
    const sharedSecret = x25519.getSharedSecret(this.privateKey, remotePublicKey);
    const transcript = concatBytes(
      textEncoder.encode('OptiLink-v1'),
      this.sessionIDBytes,
      remotePublicKey,
      this.publicKey
    );
    this.transcriptHash = sha256(transcript);
    this.dataKey = hkdf(
      sha256,
      sharedSecret,
      this.sessionIDBytes,
      concatBytes(this.transcriptHash, textEncoder.encode('data')),
      32
    );
    this.controlKey = hkdf(
      sha256,
      sharedSecret,
      this.sessionIDBytes,
      concatBytes(this.transcriptHash, textEncoder.encode('control')),
      32
    );
    this.localSequence = 0;
    this.lastRemoteSequence = undefined;
  }

  createAnswer(requestedProfileID = 'P0', detail = 'web-receiver') {
    return this.authenticate({
      protocolVersion: PROTOCOL_VERSION,
      kind: 'answer',
      sessionID: this.offer.sessionID,
      sequence: this.nextSequence(),
      publicKey: bytesToBase64(this.publicKey),
      transcriptHash: bytesToBase64(this.transcriptHash),
      capabilities: ['P0', 'P1'],
      requestedProfileID,
      detail
    });
  }

  createControl(kind, { requestedProfileID, metrics, detail } = {}) {
    return this.authenticate({
      protocolVersion: PROTOCOL_VERSION,
      kind,
      sessionID: this.offer.sessionID,
      sequence: this.nextSequence(),
      capabilities: [],
      ...(requestedProfileID ? { requestedProfileID } : {}),
      ...(metrics ? { metrics } : {}),
      ...(detail ? { detail } : {})
    });
  }

  authenticate(message) {
    const unsigned = { ...message };
    delete unsigned.authenticationTag;
    const tag = hmac(sha256, this.controlKey, textEncoder.encode(stableStringify(unsigned)));
    return { ...unsigned, authenticationTag: bytesToBase64(tag) };
  }

  verify(message) {
    if (message.sessionID !== this.offer.sessionID || !message.authenticationTag) {
      throw new Error('Control message is not authenticated for this session');
    }
    const unsigned = { ...message };
    delete unsigned.authenticationTag;
    const expected = hmac(
      sha256,
      this.controlKey,
      textEncoder.encode(stableStringify(unsigned))
    );
    if (!equalBytes(expected, base64ToBytes(message.authenticationTag))) {
      throw new Error('Control message authentication failed');
    }
    if (this.lastRemoteSequence !== undefined && message.sequence <= this.lastRemoteSequence) {
      throw new Error('Stale control message');
    }
    this.lastRemoteSequence = message.sequence;
  }

  openGeneration(combined, generationID) {
    if (combined.length < 28) throw new Error('Encrypted generation is truncated');
    const expectedNonce = sha256(concatBytes(this.transcriptHash, uint32BE(generationID))).slice(0, 12);
    const nonce = combined.slice(0, 12);
    if (!equalBytes(nonce, expectedNonce)) throw new Error('Generation nonce mismatch');
    return chacha20poly1305(this.dataKey, nonce).decrypt(combined.slice(12));
  }

  exportPrivateKey() {
    return bytesToBase64(this.privateKey);
  }

  nextSequence() {
    const value = this.localSequence;
    this.localSequence = (this.localSequence + 1) >>> 0;
    return value;
  }
}

