export const PROTOCOL_VERSION = 1;
export const CONTROL_PREFIX = 'optilink1:';
export const GENERATION_SIZE = 1_048_576;
export const RAPTORQ_SYMBOL_SIZE = 7_000;
export const OPTICAL_MAGIC = 0x4f50544c;
export const OPTICAL_HEADER_LENGTH = 48;

export const PROFILES = Object.freeze([
  Object.freeze({ id: 'P0', columns: 128, rows: 72, colorBits: 1, fps: 15, parityPercent: 30 }),
  Object.freeze({ id: 'P1', columns: 160, rows: 90, colorBits: 2, fps: 20, parityPercent: 25 })
]);

export const PALETTE = Object.freeze([
  Object.freeze([7, 17, 31]),
  Object.freeze([50, 211, 200]),
  Object.freeze([242, 181, 68]),
  Object.freeze([244, 241, 232])
]);

export function profileByID(id) {
  return PROFILES.find((profile) => profile.id === id) ?? PROFILES[0];
}

export function rawPayloadBytes(profile) {
  return Math.floor(profile.columns * profile.rows * profile.colorBits / 8);
}

