import QRCode from 'qrcode';
import './styles.css';
import { decodeControlCode, offerFromLocation } from './protocol.js';
import { BrowserOpticalDecoder } from './optical-decoder.js';
import { BrowserReceiverEngine } from './receiver-engine.js';
import { BrowserSessionStore } from './storage.js';

const app = document.querySelector('#app');

app.innerHTML = `
  <section class="receiver-shell">
    <video id="camera" class="camera-feed" playsinline muted></video>
    <div class="atmosphere"></div>
    <header class="topbar">
      <div>
        <p class="eyebrow">OPTILINK / WEB RECEIVE</p>
        <h1>让屏幕成为链路</h1>
      </div>
      <div id="secureBadge" class="secure-badge">端到端加密</div>
    </header>

    <main class="transfer-stage">
      <div class="qr-frame">
        <canvas id="feedbackQR" aria-label="OptiLink feedback QR"></canvas>
        <div class="corner corner-a"></div>
        <div class="corner corner-b"></div>
        <div class="corner corner-c"></div>
        <div class="corner corner-d"></div>
      </div>
      <p id="status" class="status">正在读取安全会话...</p>
      <p id="detail" class="detail">保持 iPhone 屏幕朝向 Mac 摄像头</p>
    </main>

    <section class="metrics-panel" aria-live="polite">
      <div class="metric"><span>状态</span><strong id="state">PAIRING</strong></div>
      <div class="metric"><span>档位</span><strong id="profile">P0</strong></div>
      <div class="metric"><span>有效速率</span><strong id="throughput">0.00 Mbps</strong></div>
      <div class="metric"><span>已接收</span><strong id="received">等待清单</strong></div>
      <div class="progress-track"><div id="progress" class="progress-value"></div></div>
    </section>

    <footer class="controls">
      <button id="startButton" class="primary-button">开启前置摄像头</button>
      <button id="pauseButton" class="secondary-button" hidden>暂停</button>
      <button id="downloadButton" class="primary-button download-button" hidden>保存 ZIP</button>
    </footer>

    <div id="blockingPanel" class="blocking-panel">
      <div class="blocking-card">
        <span class="pulse-dot"></span>
        <h2 id="blockingTitle">开始光学接收</h2>
        <p id="blockingDetail">Safari 需要一次摄像头授权。授权后，本页会显示回答二维码，并持续读取 Mac 屏幕。</p>
        <button id="blockingStartButton" class="primary-button">授权并开始</button>
        <small id="blockingNote">页面必须保持在前台。文件没有应用层大小上限，实际容量取决于设备存储和 Safari。</small>
      </div>
    </div>

    <div id="errorPanel" class="error-panel" hidden>
      <strong id="errorTitle">接收已停止</strong>
      <p id="errorText"></p>
      <button id="retryButton" class="secondary-button error-retry">重新尝试</button>
    </div>
  </section>
`;

const elements = {
  video: document.querySelector('#camera'),
  qr: document.querySelector('#feedbackQR'),
  status: document.querySelector('#status'),
  detail: document.querySelector('#detail'),
  state: document.querySelector('#state'),
  profile: document.querySelector('#profile'),
  throughput: document.querySelector('#throughput'),
  received: document.querySelector('#received'),
  progress: document.querySelector('#progress'),
  startButton: document.querySelector('#startButton'),
  blockingStartButton: document.querySelector('#blockingStartButton'),
  blockingTitle: document.querySelector('#blockingTitle'),
  blockingDetail: document.querySelector('#blockingDetail'),
  blockingNote: document.querySelector('#blockingNote'),
  blockingPanel: document.querySelector('#blockingPanel'),
  pauseButton: document.querySelector('#pauseButton'),
  downloadButton: document.querySelector('#downloadButton'),
  errorPanel: document.querySelector('#errorPanel'),
  errorTitle: document.querySelector('#errorTitle'),
  errorText: document.querySelector('#errorText'),
  retryButton: document.querySelector('#retryButton')
};

let engine;
let decoder;
let answerCode;
let cameraStarted = false;
let processingFrame = false;
let feedbackBusy = false;
let paused = false;
let frameLoopHandle;
let feedbackTimer;
let wakeLock;
let lastControlScanAt = 0;
let lastOpticalSuccessAt = 0;

function formatBytes(value) {
  if (!value) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  const index = Math.min(units.length - 1, Math.floor(Math.log(value) / Math.log(1024)));
  return `${(value / (1024 ** index)).toFixed(index === 0 ? 0 : 2)} ${units[index]}`;
}

function statusText(snapshot) {
  switch (snapshot.state) {
  case 'keyExchange': return ['等待 Mac 确认', '保持回答二维码完整可见'];
  case 'calibrating': return ['安全链路已建立', '正在识别 Mac 光学网格'];
  case 'transferring': return [snapshot.manifest ? `正在接收 ${snapshot.manifest.fileName}` : '正在接收加密清单', '请固定两台设备的位置'];
  case 'reacquiring': return ['光学链路暂停', '重新对准 Mac 屏幕，系统会自动恢复'];
  case 'verifying': return ['正在校验完整文件', '执行流式 SHA-256，请不要关闭页面'];
  case 'complete': return ['ZIP 已完整接收', '校验通过，可以保存到“文件”'];
  case 'failed': return ['接收失败', snapshot.failureMessage ?? '请重新开始会话'];
  default: return ['准备接收', '保持 iPhone 屏幕朝向 Mac 摄像头'];
  }
}

function renderSnapshot(snapshot) {
  const [status, detail] = statusText(snapshot);
  elements.status.textContent = status;
  elements.detail.textContent = detail;
  elements.state.textContent = snapshot.state.toUpperCase();
  elements.profile.textContent = snapshot.profileID;
  elements.throughput.textContent = `${snapshot.throughputMbps.toFixed(2)} Mbps`;
  elements.progress.style.width = `${(snapshot.progressFraction * 100).toFixed(2)}%`;
  elements.received.textContent = snapshot.manifest
    ? `${formatBytes(snapshot.completedBytes)} / ${formatBytes(snapshot.manifest.fileSize)}`
    : '等待清单';
  elements.downloadButton.hidden = snapshot.state !== 'complete';
  elements.pauseButton.hidden = !cameraStarted || snapshot.state === 'complete';
  if (snapshot.state === 'complete') {
    decoder?.stopCamera();
    cameraStarted = false;
    stopFrameLoop();
  }
}

async function renderQR(code) {
  const cssWidth = Math.min(430, Math.max(280, window.innerWidth * 0.76)) - 26;
  const renderWidth = Math.min(1_024, Math.max(600, Math.round(cssWidth * window.devicePixelRatio)));
  await QRCode.toCanvas(elements.qr, code, {
    errorCorrectionLevel: 'M',
    margin: 2,
    width: renderWidth,
    color: { dark: '#071012', light: '#f3f0e7' }
  });
}

async function requestWakeLock() {
  try {
    wakeLock = await navigator.wakeLock?.request('screen');
  } catch {
    wakeLock = undefined;
  }
}

function friendlyError(error) {
  const raw = error?.message ?? String(error);
  const value = `${error?.name ?? ''} ${raw}`.toLowerCase();
  if (/notallowed|permission|denied|摄像头/.test(value)) {
    return {
      title: '摄像头权限未开启',
      message: '请在 Safari 地址栏左侧的页面设置中允许“相机”，然后点“重新尝试”。'
    };
  }
  if (/indexeddb|database|storage|quota|opfs|file system/.test(value)) {
    return {
      title: '手机存储暂时不可用',
      message: '请退出无痕浏览，确认手机有可用空间，然后点“重新尝试”。'
    };
  }
  if (/offer|control code|session uuid|json|base64/.test(value)) {
    return {
      title: '会话二维码无效',
      message: '请回到 Mac 停止当前会话，重新选择“发送到手机”并扫描新二维码。'
    };
  }
  if (/webassembly|wasm|raptorq|bigint/.test(value)) {
    return {
      title: '手机浏览器不支持解码器',
      message: '请更新 iOS 后使用 Safari 重新打开二维码。'
    };
  }
  return { title: '接收初始化失败', message: `${raw}。请点“重新尝试”；如仍失败，请截图此提示。` };
}

function fail(error) {
  console.error(error);
  const friendly = friendlyError(error);
  elements.errorTitle.textContent = friendly.title;
  elements.errorText.textContent = friendly.message;
  elements.errorPanel.hidden = false;
  elements.status.textContent = friendly.title;
  stopFrameLoop();
  clearInterval(feedbackTimer);
  decoder?.stopCamera();
}

async function processCameraFrame() {
  if (!cameraStarted || processingFrame || document.hidden || !engine) return;
  processingFrame = true;
  const startedAt = performance.now();
  try {
    const imageData = decoder.capture();
    const snapshot = engine.snapshot();
    if (!engine.handshakeComplete || snapshot.state === 'reacquiring') {
      if (performance.now() - lastControlScanAt >= 160) {
        lastControlScanAt = performance.now();
        const code = decoder.scanControlCode(imageData);
        if (code?.startsWith('optilink1:')) {
          const accepted = await engine.acceptControl(decodeControlCode(code));
          if (accepted) lastOpticalSuccessAt = performance.now();
        }
      }
    } else if (!paused) {
      try {
        const result = decoder.decode(snapshot.profileID, imageData);
        await engine.acceptFrame(result.frame);
        lastOpticalSuccessAt = performance.now();
        engine.recordDecode({
          success: true,
          latencyMilliseconds: performance.now() - startedAt,
          colorConfidence: result.colorConfidence,
          finderVisible: true
        });
      } catch {
        const finderVisible = performance.now() - lastOpticalSuccessAt <= 500;
        engine.recordDecode({
          success: false,
          latencyMilliseconds: performance.now() - startedAt,
          colorConfidence: 0.5,
          finderVisible
        });
      }
    }
  } catch (error) {
    if (error?.name !== 'InvalidStateError') console.debug('Camera frame skipped:', error);
  } finally {
    processingFrame = false;
  }
}

function scheduleFrame() {
  if (!cameraStarted) return;
  if ('requestVideoFrameCallback' in HTMLVideoElement.prototype) {
    frameLoopHandle = elements.video.requestVideoFrameCallback(async () => {
      await processCameraFrame();
      scheduleFrame();
    });
  } else {
    frameLoopHandle = window.setTimeout(async () => {
      await processCameraFrame();
      scheduleFrame();
    }, 34);
  }
}

function stopFrameLoop() {
  if (!frameLoopHandle) return;
  if ('cancelVideoFrameCallback' in elements.video) {
    elements.video.cancelVideoFrameCallback(frameLoopHandle);
  } else {
    clearTimeout(frameLoopHandle);
  }
  frameLoopHandle = undefined;
}

async function updateFeedbackQR() {
  if (!engine?.handshakeComplete || feedbackBusy) return;
  feedbackBusy = true;
  try {
    const code = await engine.feedbackCode();
    await renderQR(code);
  } catch (error) {
    fail(error);
  } finally {
    feedbackBusy = false;
  }
}

async function startCamera() {
  if (cameraStarted) return;
  elements.errorPanel.hidden = true;
  elements.status.textContent = '正在启动前置摄像头...';
  try {
    await engine.prepareDecoder();
    await decoder.startCamera();
    cameraStarted = true;
    elements.blockingPanel.hidden = true;
    elements.startButton.hidden = true;
    elements.pauseButton.hidden = false;
    await requestWakeLock();
    await renderQR(answerCode);
    renderSnapshot(engine.snapshot());
    scheduleFrame();
    feedbackTimer = window.setInterval(updateFeedbackQR, 250);
  } catch (error) {
    fail(error);
  }
}

async function togglePause() {
  paused = !paused;
  elements.pauseButton.textContent = paused ? '继续' : '暂停';
  await engine.setPaused(paused);
  await updateFeedbackQR();
}

async function initialize() {
  if (!window.isSecureContext) {
    throw new Error('摄像头模式必须通过 HTTPS 打开');
  }
  if (!new URLSearchParams(window.location.hash.slice(1)).has('offer')) {
    elements.status.textContent = '接收器已就绪';
    elements.detail.textContent = '请从 Mac 的“发送到手机”二维码进入会话';
    elements.blockingTitle.textContent = 'OptiLink 已准备好';
    elements.blockingDetail.textContent = '回到 Mac，选择“发送到手机”和 ZIP，然后用 iPhone 相机扫描 Mac 屏幕上的二维码。';
    elements.blockingNote.textContent = '无需填写网址，也无需安装 App。可通过 Safari 的“添加到主屏幕”保存此接收器。';
    elements.blockingStartButton.hidden = true;
    elements.startButton.hidden = true;
    return;
  }
  const { offer } = offerFromLocation();
  const store = new BrowserSessionStore(offer.sessionID);
  engine = new BrowserReceiverEngine(offer, store);
  decoder = new BrowserOpticalDecoder(elements.video);
  engine.addEventListener('update', (event) => renderSnapshot(event.detail));
  answerCode = await engine.initialize();
  const snapshot = engine.snapshot();
  renderSnapshot(snapshot);
  if (snapshot.state === 'complete') {
    elements.blockingPanel.hidden = true;
    elements.startButton.hidden = true;
  }
}

elements.startButton.addEventListener('click', startCamera);
elements.blockingStartButton.addEventListener('click', startCamera);
elements.pauseButton.addEventListener('click', togglePause);
elements.downloadButton.addEventListener('click', async () => {
  try {
    await engine.download();
  } catch (error) {
    fail(error);
  }
});
elements.retryButton.addEventListener('click', () => window.location.reload());

document.addEventListener('visibilitychange', async () => {
  if (!engine?.handshakeComplete) return;
  await engine.setPaused(document.hidden, true);
  if (!document.hidden) {
    await requestWakeLock();
    await updateFeedbackQR();
  }
});

window.addEventListener('pagehide', () => {
  wakeLock?.release?.();
});

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').catch(console.debug));
}

initialize().catch(fail);
